(() => {
  const tc = __show.g().showControl.timecodeChase;
  const read = __show.read;
  clearInterval(window.__fakeClock);
  tc.settings.set({ ...read(tc.settings), source: 'midiClock' });
  // A MIDI clock at 132 BPM rolling from bar 3 (quarter 8) against the map's 120:
  // the map is 0.5 s a quarter from 0, so show time = quarters / 2.
  const t0 = performance.now();
  window.__fakeGen = [];
  window.__fakeClock = setInterval(() => {
    const now = performance.now();
    const q = 8 + ((now - t0) / 60000) * 132;
    tc.feedBeats(q * 0.5, now, true, 132);
    tc.step(now);
    window.__fakeGen.push(__show.g().showTimeline.seekGeneration());
  }, 16);
  return true;
})()

(() => {
  const tc = __show.g().showControl.timecodeChase;
  clearInterval(window.__fakeClock);
  // The DAW stops and locates to bar 5 (quarter 16, show 8 s).
  tc.feedBeats(8, performance.now(), false, 132);
  window.__fakeClock = setInterval(() => tc.step(performance.now()), 16);
  return true;
})()

(() => {
  const tc = __show.g().showControl.timecodeChase;
  clearInterval(window.__fakeClock);
  tc.settings.set({ ...__show.read(tc.settings), source: 'off' });
  __show.g().showTimeline.releaseChase();
  return true;
})()
